"""Load and visualize the base dataset plus the layer generated by example 1.2."""

import json
from pathlib import Path

import matplotlib.pyplot as plt
import numpy as np
from pyproj import Transformer
from sarenv import DatasetLoader, get_logger

log = get_logger()

EXAMPLE_DIRECTORY = Path(__file__).resolve().parent
DATASET_DIRECTORY = (
    EXAMPLE_DIRECTORY / "sarenv_outputs" / "radiation_area_01"
)
FIGURE_PATH = EXAMPLE_DIRECTORY / "radiation_dataset_overview.png"


def _plot_source_and_ipp(axis, item, metadata):
    """Mark the resolved radiation source and the initial planning point."""
    source_x, source_y = metadata["source_position_projected"]
    projected_crs = metadata["projected_crs"]
    transformer = Transformer.from_crs(
        "EPSG:4326", projected_crs, always_xy=True
    )
    ipp_x, ipp_y = transformer.transform(*item.center_point)

    axis.scatter(
        source_x,
        source_y,
        marker="*",
        s=150,
        color="#00e5ff",
        edgecolor="black",
        linewidth=0.7,
        label="Radiation source",
        zorder=5,
    )
    axis.scatter(
        ipp_x,
        ipp_y,
        marker="x",
        s=70,
        color="#2563eb",
        linewidth=2,
        label="IPP",
        zorder=5,
    )


def visualize_radiation_dataset(item, metadata, output_path):
    """Save a compact comparison and display-only radiation overlay."""
    radiation = item.radiation_map
    if radiation is None:
        message = "The loaded dataset does not contain radiation.npy."
        raise ValueError(message)

    minx, miny, maxx, maxy = item.bounds
    extent = (minx, maxx, miny, maxy)
    background = float(metadata["background_dose_rate"])
    valid_radiation = radiation[radiation > 0]
    radiation_max = float(valid_radiation.max())

    fig, axes = plt.subplots(1, 3, figsize=(18, 5.8))
    fig.suptitle(
        "SAREnv synthetic radiation layer — medium search region",
        fontsize=15,
        fontweight="bold",
    )

    probability_display = np.ma.masked_less_equal(item.heatmap, 0)
    probability_image = axes[0].imshow(
        probability_display,
        extent=extent,
        origin="lower",
        cmap="YlOrRd",
    )
    axes[0].set_title("Lost-person probability")
    fig.colorbar(
        probability_image,
        ax=axes[0],
        label="Probability per raster cell",
        fraction=0.046,
        pad=0.04,
    )

    radiation_display = np.ma.masked_less_equal(radiation, 0)
    radiation_image = axes[1].imshow(
        radiation_display,
        extent=extent,
        origin="lower",
        cmap="inferno",
        vmin=background,
        vmax=radiation_max,
    )
    axes[1].set_title("Gamma dose rate @ 1 m AGL")
    fig.colorbar(
        radiation_image,
        ax=axes[1],
        label="Dose rate (uSv/h)",
        fraction=0.046,
        pad=0.04,
    )
    _plot_source_and_ipp(axes[1], item, metadata)
    axes[1].legend(loc="upper right", fontsize=8)

    item.features.plot(
        ax=axes[2],
        color="#5f6b6d",
        edgecolor="#37474f",
        linewidth=0.45,
        alpha=0.38,
    )
    overlay_threshold = background + 0.02 * (radiation_max - background)
    radiation_overlay = np.ma.masked_less_equal(
        radiation, overlay_threshold
    )
    axes[2].imshow(
        radiation_overlay,
        extent=extent,
        origin="lower",
        cmap="magma",
        vmin=background,
        vmax=radiation_max,
        alpha=0.70,
    )

    rows, columns = radiation.shape
    cell_width = (maxx - minx) / columns
    cell_height = (maxy - miny) / rows
    x_centers = minx + (np.arange(columns) + 0.5) * cell_width
    y_centers = miny + (np.arange(rows) + 0.5) * cell_height
    contour_levels = np.linspace(
        background, radiation_max, num=6
    )[1:-1]
    axes[2].contour(
        x_centers,
        y_centers,
        radiation,
        levels=contour_levels,
        colors="white",
        linewidths=0.7,
        alpha=0.85,
    )
    _plot_source_and_ipp(axes[2], item, metadata)
    axes[2].set_title("OSM features + radiation overlay")
    axes[2].legend(loc="upper right", fontsize=8)

    for axis in axes:
        axis.set_xlabel("Easting (m)")
        axis.set_ylabel("Northing (m)")
        axis.set_aspect("equal")
        axis.set_xlim(minx, maxx)
        axis.set_ylim(miny, maxy)

    fig.tight_layout()
    fig.savefig(output_path, dpi=200, bbox_inches="tight")
    plt.close(fig)
    return output_path


def run_radiation_loading_example():
    """Load the medium crop, report key data, and save one overview image."""
    log.info("--- Starting Radiation Dataset Loading Example ---")
    size_to_load = "medium"

    loader = DatasetLoader(dataset_directory=str(DATASET_DIRECTORY))
    item = loader.load_environment(size_to_load)
    if item is None:
        message = f"Could not load dataset size '{size_to_load}'."
        raise RuntimeError(message)
    if item.radiation_map is None:
        message = f"No radiation.npy found in {DATASET_DIRECTORY}."
        raise FileNotFoundError(message)

    metadata_path = DATASET_DIRECTORY / "radiation_meta.json"
    metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
    radiation_inside_mask = item.radiation_map[item.radiation_map > 0]

    log.info("--- Radiation-enabled dataset loaded successfully ---")
    log.info(
        f"Loaded size: {item.size}; radius: {item.radius_km:.1f} km; "
        f"shape: {item.heatmap.shape}"
    )
    log.info(
        f"Probability retained in crop: {item.heatmap.sum():.6f}; "
        f"clipped feature count: {len(item.features)}"
    )
    log.info(
        "Radiation in crop: "
        f"background={metadata['background_dose_rate']:.2f}, "
        f"max={radiation_inside_mask.max():.4f}, "
        f"mean={radiation_inside_mask.mean():.4f} uSv/h"
    )
    log.info(
        "Source: "
        f"distance={metadata['source_distance_m']:.1f} m, "
        f"bearing={metadata['source_angle_deg']:.1f} degrees"
    )

    figure_path = visualize_radiation_dataset(
        item, metadata, FIGURE_PATH
    )
    log.info(f"Saved visualization: {figure_path}")
    return item, metadata, figure_path


if __name__ == "__main__":
    run_radiation_loading_example()
